function HomeRedirect() {
  const { isLoaded, isSignedIn } = useAuth();
  if (!isLoaded) return <LoadingScreen />;
  return isSignedIn ? <Redirect to="/dashboard" /> : <PublicHome />;
}

function LoadingScreen() { return <div className="grid min-h-[100dvh] place-items-center bg-background"><div className="flex items-center gap-3 text-sm font-bold text-muted-foreground"><span className="h-2 w-2 animate-pulse rounded-full bg-primary" /> A preparar o seu espaço...</div></div>; }

const nav = [
  { href: '/dashboard', label: 'Visão geral', icon: LayoutDashboard },
  { href: '/products', label: 'Produtos', icon: Package },
  { href: '/stock', label: 'Stock', icon: Boxes },
  { href: '/sales', label: 'Vendas', icon: ShoppingCart },
  { href: '/customers', label: 'Clientes', icon: Users },
  { href: '/categories', label: 'Categorias', icon: Tags },
];

